<template><view v-if="pet && !memorial && (recordFollowup || followup || proposal)" class="companion-prompt">
 <template v-if="recordFollowup"><text class="prompt-title">还有一条你记录的照护后续</text><button class="prompt-link" @click="openRecordFollowup">查看原事件与后续</button></template><template v-else-if="followup"><text class="prompt-title">{{tr('careContinue')}}</text><text class="prompt-copy">{{followup.question}}</text><button class="prompt-link" @click="care">{{tr('viewFollowup')}}</button></template>
 <template v-else-if="proposal"><view class="prompt-heading"><button class="prompt-toggle" :aria-expanded="expanded" @click="expanded=!expanded"><view class="prompt-emblem"><uni-icons type="heart" size="18" color="currentColor"/></view><text class="prompt-title">{{tr('proposalTitle')}}</text><uni-icons :type="expanded?'top':'bottom'" size="13" color="currentColor"/></button><button class="prompt-more" :aria-label="v('more')" @click="more"><uni-icons type="more-filled" size="20" color="currentColor"/></button></view><text v-if="expanded" class="prompt-copy">{{tr('proposal_'+proposal.id)}}</text><view v-if="expanded" class="prompt-actions"><button class="prompt-write" @click="write">{{tr('noteIt')}} <uni-icons type="arrowright" size="16" color="currentColor"/></button><button class="prompt-change" @click="change('next')">{{tr('another')}}</button></view></template>
</view></template>
<script>
import {getNarrativeStore,narrativeMode} from '../../common/narrative-store.js';
import {currentProposal,changeProposal} from '../../common/companion-proposals.js';
import {getConsultationRecords} from '../../common/consultation-store.js';
import {getActivePet} from '../../common/pet-store.js';
import {t} from '../../common/i18n.js';
export default{props:{pet:Object,refresh:Number},data:()=>({expanded:false,proposal:null,followup:null,recordFollowup:null,store:null}),computed:{memorial(){return narrativeMode(this.pet?.relationshipStage||this.pet?.status)==='deceased';}},watch:{pet:{immediate:true,handler(){this.load();}},refresh(){this.load();}},methods:{v(k){return t("creative."+k);},async more(){const actions=["save","unsuitable","close"];try{const r=await new Promise((success,fail)=>uni.showActionSheet({itemList:[this.tr("later"),this.tr("unsuitable"),this.tr("closeProposal")],success,fail}));this.change(actions[r.tapIndex]);}catch(_){}},tr(k){return t('narrative.'+k);},load(){this.proposal=null;this.followup=null;this.recordFollowup=null;if(!this.pet||this.memorial)return;try{this.store=getNarrativeStore(this.pet.id);const records=this.store.list();const latest=new Map();for(const r of records.filter(r=>r.mode==='current'&&r.careSourceId).sort((a,b)=>a.createdAt-b.createdAt))latest.set(r.careSourceId,r);const pending=[...latest.values()].find(r=>['observing','changed','visited'].includes(r.careStatus)&&records.some(source=>source.id===r.careSourceId));if(pending){this.recordFollowup=pending.careSourceId;return;}const follows=this.store.read().followups;this.followup=getConsultationRecords(this.pet.id).find(r=>follows[r.id]?.at&&['changed','visited'].includes(follows[r.id].status));if(!this.followup)this.proposal=currentProposal(this.store,this.pet.species);}catch(_){this.proposal=null;}},change(action){if(getActivePet()?.id!==this.pet.id)return;this.proposal=changeProposal(this.store,this.pet.species,action);},openRecordFollowup(){if(getActivePet()?.id!==this.pet.id||this.memorial)return;try{if(!this.store.list().some(r=>r.id===this.recordFollowup)){this.load();return;}uni.navigateTo({url:'/pages/calendar/calendar?section=health&'+(this.recordFollowup.startsWith('legacy:')?'date='+this.recordFollowup.slice(7):'recordId='+encodeURIComponent(this.recordFollowup))});}catch(_){this.load();}},write(){uni.navigateTo({url:'/pages/calendar/calendar'});},care(){uni.navigateTo({url:'/pages/care/care'});}}};
</script>
<style scoped>
.companion-prompt{margin:16px 0 0;padding:12px 16px;border:1px solid rgba(221,228,202,.07);border-radius:20px;background:linear-gradient(120deg,#2d3026,#292b23);color:var(--ui-ink)}
button{box-sizing:border-box;margin:0;padding:0;background:transparent;color:inherit;border:0;border-radius:0;line-height:1.6;text-align:left}button::after{border:0}
.prompt-heading{display:flex;justify-content:space-between;align-items:center;gap:8px}.prompt-toggle{display:flex;align-items:center;gap:12px;flex:1;min-width:0;min-height:48px}.prompt-emblem{display:flex;align-items:center;justify-content:center;flex:0 0 36px;height:36px;color:#c1cbae;border-radius:12px;background:rgba(188,196,174,.06)}.prompt-title{display:block;font-size:calc(14px * var(--ui-font-scale,1));line-height:1.7;color:var(--ui-ink);font-weight:500}.prompt-toggle .prompt-title{flex:1}.prompt-toggle>.uni-icons{color:var(--ui-muted)}
.prompt-copy{display:block;font-size:calc(14px * var(--ui-font-scale,1));line-height:1.85;color:var(--ui-muted);margin:14px 4px 18px;overflow-wrap:anywhere}.prompt-actions{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:0 4px 6px}.prompt-actions button,.prompt-link{font-size:calc(13px * var(--ui-font-scale,1));color:var(--ui-muted);min-height:44px}.prompt-actions .prompt-write{display:flex;align-items:center;justify-content:center;gap:10px;border:1px solid var(--ui-line);border-radius:12px;padding:10px 16px;background:#373f2e;color:#e1e7d6}.prompt-change{padding:8px}.prompt-more{display:flex;align-items:center;justify-content:center;width:44px;min-height:44px;flex-shrink:0;color:var(--ui-muted)}.prompt-link{display:flex;align-items:center;padding:8px 0}
</style>
